  ('w_m_push', 'c_marko', 'Push day', '[{"exerciseId":"m_bench","sets":4,"repsMin":6,"repsMax":8,"rir":2,"restSeconds":150},{"exerciseId":"m_ohp","sets":3,"repsMin":8,"repsMax":10,"rir":2,"restSeconds":120},{"exerciseId":"m_incline_db","sets":3,"repsMin":10,"repsMax":12,"rir":1,"restSeconds":90},{"exerciseId":"m_lateral","sets":3,"repsMin":12,"repsMax":15,"rir":1,"restSeconds":60},{"exerciseId":"m_pushdown","sets":3,"repsMin":12,"repsMax":12,"rir":1,"restSeconds":60}]'::jsonb, 'Dobar potisak. Sledeće je Pull. Isti ritam.', 'public'),
